import pandas as pd


def normalize(source_path: str) -> pd.DataFrame:
    """
    Normalize sales data from CSV to canonical form.

    Reads a source file containing columns: Country, Product, Month, Sales.
    Returns a DataFrame with columns: country, product_id, period, sales.

    Uses Escalate/AskHuman if ambiguous values are encountered during processing.
    """
    from contract import Escalate, AskHuman

    try:
        # Load the data
        df = pd.read_csv(source_path)

        # Validate expected columns exist
        required_cols = {"Country", "Product", "Month", "Sales"}
        if set(df.columns) != required_cols:
            missing = required_cols - set(df.columns)
            raise ValueError(f"Missing expected source columns: {missing}")

        # Map and clean country (ensure uppercase, strip whitespace)
        df["country"] = df["Country"].astype(str).str.strip().upper()

        # Map product identifier directly (preserve exact business ID as string)
        df["product_id"] = df["Product"].astype(str).str.strip()

        # Handle Month: source is YYYY-MM, ensure it stays in that format for 'period'
        raw_month_str = df["Month"]
        def safe_parse_period(m):
            val = str(m).strip().upper()
            if not val.endswith('-MM') and '-' in val:
                return val # Assume already correct YYYY-MM
            try:
                dt = pd.to_datetime(val, format="%Y-%m")
                return dt.strftime("%Y-%m").lower() 
            except Exception as e:
                 raise Escalate(f"Failed to parse month value '{val}': {e}") from None

        df["period"] = raw_month_str.apply(safe_parse_period) 

        # Convert Sales to numeric, handling potential parsing issues
        def safe_convert_numeric(val):
            try:
                num_val = float(str(val).strip().replace(',', ''))
                return round(num_val, 2)
            except Exception as e:
                 raise Escalate(f"Failed to convert sales value '{val}': {e}") from None

        df["sales"] = df["Sales"].apply(safe_convert_numeric)

        # Check for nulls introduced by conversion (ambiguous data)
        if df["sales"].isna().any():
            raise Escalate("Ambiguous or invalid numeric values detected in 'Sales' column.")

        # Construct final canonical DataFrame with required columns and deterministic ordering
        result = pd.DataFrame({
            "country": df["country"],
            "product_id": df["product_id"],
            "period": df["period"],
            "sales": df["sales"]
        })

        return result.sort_values(["country", "product_id", "period"]).reset_index(drop=True)

    except Exception as e:
        # If parsing fails due to unexpected structure or data, escalate immediately without guessing.
        raise Escalate(f"Normalization failed with error: {e}") from None
